import { StyleSheet, View, type ViewStyle } from 'react-native';

import { webStyle } from '@/theme/web';

/**
 * Crumpled paper, generated by the browser: ridged turbulence lit from the top left, so the creases
 * catch light on one side and shade on the other. It tiles seamlessly at 640 px and is multiplied
 * over the sheet's own color at low strength, so it reads as texture, never as pattern. No image
 * file ships; on native the sheet stays flat.
 */
const TEXTURE =
  "url(\"data:image/svg+xml;utf8," +
  "<svg xmlns='http://www.w3.org/2000/svg' width='640' height='640'>" +
  "<filter id='c' x='0' y='0' width='100%25' height='100%25'>" +
  "<feTurbulence type='turbulence' baseFrequency='0.0055 0.0075' numOctaves='4' seed='11' stitchTiles='stitch' result='n'/>" +
  "<feDiffuseLighting in='n' lighting-color='%23ffffff' surfaceScale='5' diffuseConstant='1.05' result='l'>" +
  "<feDistantLight azimuth='225' elevation='42'/>" +
  '</feDiffuseLighting>' +
  "<feColorMatrix in='l' type='saturate' values='0'/>" +
  '</filter>' +
  "<rect width='100%25' height='100%25' filter='url(%23c)'/>" +
  '</svg>")';

const paper = webStyle<ViewStyle>({
  backgroundImage: TEXTURE,
  backgroundSize: '640px 640px',
  mixBlendMode: 'multiply',
  opacity: 0.38,
});

/** Lays the crumple over its parent. Put it first so content sits above it. */
export function Crumple() {
  if (!paper) return null;
  return <View aria-hidden pointerEvents="none" style={[styles.fill, paper]} />;
}

const styles = StyleSheet.create({
  fill: { position: 'absolute', top: 0, right: 0, bottom: 0, left: 0 },
});
